package com.company.tpm.training; import com.company.tpm.common.BaseEntity; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="training_courses") public class TrainingCourse extends BaseEntity{@Column(nullable=false,unique=true)private String code;@Column(nullable=false)private String name;private String description;@Column(nullable=false)private boolean required;@Column(nullable=false,precision=5,scale=2)private BigDecimal passMark;@Column(nullable=false,precision=8,scale=2)private BigDecimal maximumScore;private Integer durationMinutes;private Integer validityMonths;private String instructor;@Column(nullable=false)private boolean active=true;protected TrainingCourse(){}public String getCode(){return code;}public String getName(){return name;}public BigDecimal getPassMark(){return passMark;}public BigDecimal getMaximumScore(){return maximumScore;}}
